insert into app.meeting_uploads (id, meeting_id, transcript_id, storage_path, filename, mime, size_bytes, state, uploaded_by, created_at, parsed_at)
  values ('522c5607-cb9d-4738-ac84-8ab792d77f89', '81516757-2c18-48a8-a76a-f586ad9bfcd7', '569d4457-61fb-4dc5-a855-1717bdc8c617', 'upload/' || '81516757-2c18-48a8-a76a-f586ad9bfcd7' || '/' || '522c5607-cb9d-4738-ac84-8ab792d77f89' || '.vtt', 'Discovery call — Kystlinje.vtt', 'text/vtt', 2318, 'parsed', '5f3f5ad9-1a54-44ac-a57f-57a6320f4ceb', ((case when ((((now() at time zone 'Europe/Oslo')::date + 0) + time '09:00') at time zone 'Europe/Oslo') < now() then ((((now() at time zone 'Europe/Oslo')::date + 0) + time '09:00') at time zone 'Europe/Oslo') else ((((now() at time zone 'Europe/Oslo')::date + -1) + time '09:00') at time zone 'Europe/Oslo') end) + interval '50 minutes') - interval '1 minute', ((case when ((((now() at time zone 'Europe/Oslo')::date + 0) + time '09:00') at time zone 'Europe/Oslo') < now() then ((((now() at time zone 'Europe/Oslo')::date + 0) + time '09:00') at time zone 'Europe/Oslo') else ((((now() at time zone 'Europe/Oslo')::date + -1) + time '09:00') at time zone 'Europe/Oslo') end) + interval '50 minutes'));
insert into app.transcript_segments (transcript_id, seq, start_ms, speaker_label, text) values ('569d4457-61fb-4dc5-a855-1717bdc8c617', 1, 12000, 'Tor', 'Takk for at dere tok dere tid. Skal vi starte med hvordan bytter fungerer i dag?');
insert into app.transcript_segments (transcript_id, seq, start_ms, speaker_label, text) values ('569d4457-61fb-4dc5-a855-1717bdc8c617', 2, 31000, 'Camilla', 'I dag går alt på telefon og en delt Excel. Vi er 220 sjåfører fordelt på tre depoter.');
insert into app.transcript_segments (transcript_id, seq, start_ms, speaker_label, text) values ('569d4457-61fb-4dc5-a855-1717bdc8c617', 3, 125000, 'Tor', 'Da passer Skiftly per depot. Hva skjer når noen blir syke på natta?');
insert into app.transcript_segments (transcript_id, seq, start_ms, speaker_label, text) values ('569d4457-61fb-4dc5-a855-1717bdc8c617', 4, 160000, 'Camilla', 'Vaktsjefen ringer rundt. Vi vil gjerne ha det på plass før jul — budsjettet er godkjent for fire hundre tusen.');
insert into app.transcript_segments (transcript_id, seq, start_ms, speaker_label, text) values ('569d4457-61fb-4dc5-a855-1717bdc8c617', 5, 318000, 'Camilla', 'HR-sjefen vår, Nora Berg, må være med på neste møte.');
insert into app.transcript_segments (transcript_id, seq, start_ms, speaker_label, text) values ('569d4457-61fb-4dc5-a855-1717bdc8c617', 6, 422000, 'Tor', 'Jeg sender et forslag innen fredag, og vi booker en demo med Nora.');
insert into app.transcript_speakers (transcript_id, label, staff_id, email) values ('569d4457-61fb-4dc5-a855-1717bdc8c617', 'Tor', '5f3f5ad9-1a54-44ac-a57f-57a6320f4ceb', 'tor@orgpuls.no');
insert into app.transcript_speakers (transcript_id, label) values ('569d4457-61fb-4dc5-a855-1717bdc8c617', 'Camilla');
